function TaskItem({ task, onToggle, onRemove }) {
  return (
    <li>
      <span
        onClick={() => onToggle(task.id)}
        style={{ textDecoration: task.done ? 'line-through' : 'none' }}
      >
        {task.text}
      </span>
      <button onClick={() => onRemove(task.id)}>Delete</button>
    </li>
  );
}

function TaskList({ tasks, onToggle, onRemove }) {
  if (tasks.length === 0) {
    return <p>No tasks yet. Add your first one!</p>;
  }
  return (
    <ul>
      {tasks.map((task) => (
        <TaskItem
          key={task.id}
          task={task}
          onToggle={onToggle}
          onRemove={onRemove}
        />
      ))}
    </ul>
  );
}
